    /**
     * Returns every state permutation for a block, in ordinal order.
     *
     * @param key namespaced block identifier
     * @return the block's states, or {@code null} if unknown
     */
    public static BlockState[] statesOf(final Key key) {
        return BY_KEY.get(key);
    }

    /**
     * Returns the state at a specific ordinal for a block.
     *
     * @param key     namespaced block identifier
     * @param ordinal state ordinal, see {@code BlockType}
     * @return the matching state
     */
    public static BlockState stateAt(final Key key, final int ordinal) {
        return BY_KEY.get(key)[ordinal];
    }

    /**
     * Returns the default state for a block.
     *
     * @param key namespaced block identifier
     * @return the default state, or {@code null} if unknown
     */
    public static BlockState defaultStateOf(final Key key) {
        return DEFAULT.get(key);
    }

